<section id="contact" style="background: #F2F6FB">
<div class="wrap sec" style="box-sizing: border-box; width: 100%; max-width: 1240px; margin: 0 auto; padding: 0 32px; display: flex; flex-wrap: wrap; gap: 64px; padding-top: 104px; padding-bottom: 104px">
<div style="flex: 1 1 380px; min-width: 0; display: flex; flex-direction: column; gap: 20px">
<p style="margin: 0; font-family: Montserrat, sans-serif; font-weight: 700; font-size: 13px; letter-spacing: 0.18em; text-transform: uppercase; color: #0B5FC4">Contact</p>
<h2 style="margin: 0; font-family: Montserrat, sans-serif; font-weight: 700; font-size: 38px; line-height: 1.15; letter-spacing: -0.01em; color: #14213A">Get in touch.</h2>
<p style="margin: 0; font-size: 18px; line-height: 1.6; color: #3D4A60">Send us a message and we will get back to you.</p>
<div style="display: flex; flex-direction: column; gap: 10px; padding-top: 8px; font-size: 16px; color: #3D4A60">
<a href="mailto:juccallc@yahoo.com" style="font-weight: 600; text-decoration: underline; padding: 10px 0; align-self: flex-start">juccallc@yahoo.com</a>
<span>Florida, U.S.A.</span>
</div>
</div>
<form id="contact-form" action="{{AJAX}}" method="POST" style="flex: 1 1 520px; min-width: 0; box-sizing: border-box; background: #FFFFFF; border: 1px solid #D9E2EE; border-radius: 8px; padding: 36px; display: flex; flex-direction: column; gap: 20px">
<div style="display: flex; flex-wrap: wrap; gap: 20px">
<div style="display: flex; flex-direction: column; gap: 6px; flex: 1 1 240px">
<label for="f-name" style="font-size: 14px; font-weight: 600; color: #14213A">Full name</label>
<input id="f-name" name="name" type="text" autocomplete="name" required placeholder="" style="box-sizing: border-box; width: 100%; height: 48px; padding: 0 14px; font: inherit; font-size: 16px; color: #14213A; background: #FFFFFF; border: 1px solid #A9B8CC; border-radius: 6px">
</div>
<div style="display: flex; flex-direction: column; gap: 6px; flex: 1 1 240px">
<label for="f-company" style="font-size: 14px; font-weight: 600; color: #14213A">Company</label>
<input id="f-company" name="company" type="text" autocomplete="organization" placeholder="" style="box-sizing: border-box; width: 100%; height: 48px; padding: 0 14px; font: inherit; font-size: 16px; color: #14213A; background: #FFFFFF; border: 1px solid #A9B8CC; border-radius: 6px">
</div>
</div>
<div style="display: flex; flex-wrap: wrap; gap: 20px">
<div style="display: flex; flex-direction: column; gap: 6px; flex: 1 1 240px">
<label for="f-email" style="font-size: 14px; font-weight: 600; color: #14213A">Email</label>
<input id="f-email" name="email" type="email" autocomplete="email" required placeholder="" style="box-sizing: border-box; width: 100%; height: 48px; padding: 0 14px; font: inherit; font-size: 16px; color: #14213A; background: #FFFFFF; border: 1px solid #A9B8CC; border-radius: 6px">
</div>
</div>
<div style="display: flex; flex-direction: column; gap: 6px">
<label for="f-msg" style="font-size: 14px; font-weight: 600; color: #14213A">Message</label>
<textarea id="f-msg" name="message" rows="5" required style="box-sizing: border-box; width: 100%; padding: 12px 14px; font: inherit; font-size: 16px; color: #14213A; background: #FFFFFF; border: 1px solid #A9B8CC; border-radius: 6px; resize: vertical"></textarea>
</div>
<div aria-hidden="true" style="position: absolute; left: -9999px; width: 1px; height: 1px; overflow: hidden"><label for="f-website">Website</label><input id="f-website" type="text" name="website" tabindex="-1" autocomplete="off"></div>
<input type="hidden" name="action" value="jucca_contact">
<p id="form-status" role="status" aria-live="polite" style="margin: 0; min-height: 22px; font-size: 15px; font-weight: 600; color: #14213A"></p>
<button type="submit" style="display: inline-flex; align-items: center; justify-content: center; min-height: 48px; padding: 0 26px; border-radius: 6px; font-family: Montserrat, sans-serif; font-weight: 700; font-size: 15px; text-decoration: none; box-sizing: border-box; align-self: flex-start; border: 0; background: #0B5FC4; color: #FFFFFF; cursor: pointer">Send message</button>
</form>
</div>
</section>

<footer style="background: #0A2250">
<div class="wrap" style="box-sizing: border-box; width: 100%; max-width: 1240px; margin: 0 auto; padding: 0 32px; display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 20px 40px; padding-top: 40px; padding-bottom: 40px">
<div style="display: flex; flex-direction: column; gap: 6px">
<span style="font-family: Montserrat, sans-serif; font-weight: 800; font-size: 20px; letter-spacing: 0.04em; color: #FFFFFF">JUCCA LLC</span>
<span style="font-family: Montserrat, sans-serif; font-weight: 600; font-size: 12px; letter-spacing: 0.18em; color: #C9D8EE">IMPORT · EXPORT · GLOBAL TRADE</span>
</div>
<span style="font-size: 14px; color: #C9D8EE">© 2026 JUCCA LLC. Florida, U.S.A.</span>
</div>
</footer>

</div>
<script>
(function () {
  var M = {"sending": "Sending...", "ok": "Thank you. Your message was sent.", "fail": "The message could not be sent. Please email us at juccallc@yahoo.com."};
  var header = document.querySelector(".site-header"), burger = document.querySelector("[data-burger]");
  function closeMenu() { header.classList.remove("open"); burger.setAttribute("aria-expanded", "false"); }
  burger.addEventListener("click", function () {
    var open = header.classList.toggle("open");
    burger.setAttribute("aria-expanded", open ? "true" : "false");
  });
  document.querySelectorAll("#site-nav a, .site-actions a").forEach(function (a) { a.addEventListener("click", closeMenu); });
  var form = document.getElementById("contact-form"), status = document.getElementById("form-status"), loadedAt = Date.now();
  form.addEventListener("submit", function (e) {
    e.preventDefault();
    var data = new FormData(form), elapsed = Date.now() - loadedAt;
    if (data.get("website") || elapsed < 3000) { status.textContent = M.ok; form.reset(); return; }
    data.append("elapsed", String(elapsed));
    data.append("lang", document.documentElement.lang === "es" ? "es" : "en");
    var btn = form.querySelector('button[type="submit"]');
    btn.disabled = true; status.textContent = M.sending;
    fetch(form.getAttribute("action"), { method: "POST", headers: { Accept: "application/json" }, body: data, credentials: "same-origin" })
      .then(function (r) { return r.json().then(function (j) { return r.ok && j.success === true; }); })
      .then(function (ok) { status.textContent = ok ? M.ok : M.fail; if (ok) { form.reset(); loadedAt = Date.now(); } })
      .catch(function () { status.textContent = M.fail; })
      .then(function () { btn.disabled = false; });
  });
})();
</script>
